// ?GetRegistryUseLocalUserMaps@@YA_NXZ
// partial score=0.9485 date=2026-09-29
// ?GetRegistryUseLocalUserMaps@@YA_NXZ
// Probe reproduces retail's 136-byte body with 11 relocations and 7 non-relocation
// bytes; the only residue is that retail reserves 8 bytes of frame where VC7.1
// reserves 12.  Retail's out-param home is frame offset 0, which is also the
// first by-value AsciiString saved-esp record's slot; VC7.1 gives the
// address-taken local its own dword and shifts seven stack operands by four.
// 14 sessions (docs/shape_levers.md rows 37, 38, 41, 76, 77, 79) have swept
// source shape, scope, block nesting, argument spelling, flag combinations,
// shim variants and the AsciiString inline/out-of-line dtor split.  An
// image-wide scan (build/w7/search_alias.py, 366 sites where a lea of a frame
// slot coincides with an EH saved-esp record store) finds NO other function
// with sub esp,8 plus two records, so no sibling body teaches the spelling.
// cl: /DNDEBUG /DWIN32 /D_WINDOWS /MD /EHsc /Iinputs/reference/shims/asciistring_downloadmanager /Iinputs/reference/CnC_Generals_Zero_Hour/GeneralsMD/Code/GameEngine/Include /Iinputs/reference/CnC_Generals_Zero_Hour/GeneralsMD/Code/Libraries/Source/WWVegas/WWLib

#include "Common/AsciiString.h"

bool GetUnsignedIntFromRegistry(AsciiString path, AsciiString key, unsigned int &val);

bool GetRegistryUseLocalUserMaps(void)
{
	static int value = -1;
	if (value < 0)
	{
		unsigned int registryValue;
		value = GetUnsignedIntFromRegistry("", "UseLocalUserMaps", registryValue)
			? registryValue
			: 1;
	}

	return value != 0;
}
